SELECT doc_id, notice_id, doc_title, doc_category, standard_code, file_path, ocr_engine, chunk_count, parse_status, create_by, create_time FROM ehs_kb_document
AND doc_title ILIKE '%' || #{docTitle} || '%' AND doc_category = #{docCategory}
ORDER BY doc_id DESC

SELECT doc_id, notice_id, doc_title, doc_category, standard_code, file_path, ocr_engine, chunk_count, parse_status, create_by, create_time
FROM ehs_kb_document
WHERE doc_id = #{docId}
